```python
person = {"name": "Alice", "age": 30}

for key in person:
    print(key)                    # name, age

for key, value in person.items():
    print(key, "->", value)       # name -> Alice / age -> 30

for value in person.values():
    print(value)                  # Alice, 30
```

```python
a = {1, 2, 3}
b = {2, 3, 4}

a | b   # union: {1, 2, 3, 4}
a & b   # intersection: {2, 3}
a - b   # difference: {1}
a ^ b   # symmetric difference: {1, 4}
```

